<#
.SYNOPSIS
Offline tests for Step-Header.ps1 on synthetic STEP text. No Inventor, Vault or network.
Run:  & .\windows\Test-StepHeader.ps1      Exit code 0 when all cases pass.
#>
$ErrorActionPreference = "Stop"
. (Join-Path $PSScriptRoot "Step-Header.ps1")
$results = @()
function Case($name, [scriptblock]$body) {
    try { $detail = & $body; $script:results += [ordered]@{ case = $name; passed = $true; detail = "$detail" }; Write-Output "PASS $name $(if ($detail) { "- $detail" })" }
    catch { $script:results += [ordered]@{ case = $name; passed = $false; detail = $_.Exception.Message }; Write-Output "FAIL $name - $($_.Exception.Message)" }
}
function Assert($cond, $msg) { if (-not $cond) { throw $msg } }
function Throws([scriptblock]$body, [string]$pattern) { try { & $body | Out-Null } catch { if ($_.Exception.Message -match $pattern) { return $true }; throw "threw '$($_.Exception.Message)', expected /$pattern/" }; throw "did not throw (expected /$pattern/)" }
$latin1 = [Text.Encoding]::GetEncoding(28591)
$work = Join-Path $env:TEMP ("vault-cad-step-header-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $work | Out-Null
function New-Step([string]$name, [string]$text) { $path = Join-Path $work $name; [IO.File]::WriteAllBytes($path, $latin1.GetBytes($text)); return $path }
function Sha([byte[]]$bytes, [int]$offset) { $h = [Security.Cryptography.SHA256]::Create(); try { ([BitConverter]::ToString($h.ComputeHash($bytes, $offset, $bytes.Length - $offset)) -replace '-', '').ToLowerInvariant() } finally { $h.Dispose() } }

# The header Inventor's translator writes (comments inside the statements, CRLF), with a made-up author.
$inventorHeader = "ISO-10303-21;`r`nHEADER;`r`n/* Generated by software containing ST-Developer`r`n * from STEP Tools, Inc. (www.steptools.com) `r`n */`r`n`r`nFILE_DESCRIPTION(`r`n/* description */ (''),`r`n/* implementation_level */ '2;1');`r`n`r`nFILE_NAME(`r`n/* name */ 'PLATE__[Primary]__0a1b2c3d.step',`r`n/* time_stamp */ '2026-10-21T15:09:10-04:00',`r`n/* author */ ('someone'),`r`n/* organization */ (''),`r`n/* preprocessor_version */ 'ST-DEVELOPER v20',`r`n/* originating_system */ 'Autodesk Inventor 2025',`r`n/* authorisation */ '');`r`n`r`nFILE_SCHEMA (('AUTOMOTIVE_DESIGN { 1 0 10303 214 3 1 1 }'));`r`nENDSEC;`r`n`r`n"
$dataSection = "DATA;`r`n#10=PRODUCT('PLATE','PLATE','',(#20));`r`n#11=CARTESIAN_POINT('a;b''c',(0.,0.,0.));`r`nENDSEC;`r`nEND-ISO-10303-21;`r`n"
$inventorFile = New-Step "inventor.step" ($inventorHeader + $dataSection)
$expectedStatement = "FILE_NAME('part.step','1970-01-01T00:00:00',(''),(''),'ST-DEVELOPER v20','Autodesk Inventor 2025','');"

try {
    Case "H1 Inventor-style header (comments, CRLF, '2;1' with a semicolon inside a string): fields parsed" {
        $info = Get-StepFileInfo -Path $inventorFile
        Assert ($info.header.name -eq "PLATE__[Primary]__0a1b2c3d.step" -and $info.header.time_stamp -eq "2026-10-21T15:09:10-04:00") "name/time: $($info.header.name) / $($info.header.time_stamp)"
        Assert ((@($info.header.author) -join '|') -eq "someone" -and (@($info.header.organization) -join '|') -eq "" -and @($info.header.organization).Count -eq 1) "author/organization: $(@($info.header.author) -join '|') / $(@($info.header.organization).Count)"
        Assert ($info.header.preprocessor_version -eq "ST-DEVELOPER v20" -and $info.header.originating_system -eq "Autodesk Inventor 2025" -and $info.header.authorisation -eq "") "preprocessor/originating/authorisation"
        Assert ($info.header.implementation_level -eq "2;1" -and $info.header.schema -eq "AUTOMOTIVE_DESIGN { 1 0 10303 214 3 1 1 }" -and $info.header.protocol -eq "AP214") "implementation level / schema / protocol: $($info.header.implementation_level) / $($info.header.schema) / $($info.header.protocol)"
        Assert ($info.line_ending -eq "CRLF") "line ending $($info.line_ending)"
        "protocol $($info.header.protocol)"
    }
    Case "H2 data_sha256 is the hash of the bytes from the DATA keyword to the end of the file" {
        $info = Get-StepFileInfo -Path $inventorFile
        $bytes = [IO.File]::ReadAllBytes($inventorFile)
        Assert ($info.data_offset -eq $inventorHeader.Length) "data offset $($info.data_offset), expected $($inventorHeader.Length)"
        Assert ($info.data_sha256 -eq (Sha $bytes $inventorHeader.Length) -and $info.sha256 -eq (Sha $bytes 0) -and $info.bytes -eq $bytes.Length) "hashes or size differ"
        "offset $($info.data_offset)"
    }
    Case "H3 normalised header: only the FILE_NAME statement changes, to the exact text of the layout specification" {
        $out = Join-Path $work "normalised.step"
        $done = Set-StepFileHeader -Path $inventorFile -OutPath $out
        $before = $latin1.GetString([IO.File]::ReadAllBytes($inventorFile)); $after = $latin1.GetString([IO.File]::ReadAllBytes($out))
        $start = $before.IndexOf("FILE_NAME("); $endBefore = $before.IndexOf(";", $before.IndexOf("/* authorisation */")) + 1
        Assert ($done.new_statement -eq $expectedStatement) "statement: $($done.new_statement)"
        Assert ($after -eq ($before.Substring(0, $start) + $expectedStatement + $before.Substring($endBefore))) "bytes outside the FILE_NAME statement changed"
        $info = Get-StepFileInfo -Path $out; $original = Get-StepFileInfo -Path $inventorFile
        Assert ($info.data_sha256 -eq $original.data_sha256 -and $done.data_sha256_unchanged -and $info.sha256 -ne $original.sha256) "data hash changed or file unchanged"
        Assert ($info.header.name -eq "part.step" -and $info.header.time_stamp -eq "1970-01-01T00:00:00" -and (@($info.header.author) -join '|') -eq "" -and @($info.header.author).Count -eq 1 -and $info.header.authorisation -eq "" -and $info.header.originating_system -eq "Autodesk Inventor 2025") "normalised fields wrong"
        "data hash kept, $($original.bytes) -> $($info.bytes) bytes"
    }
    Case "H4 normalising twice gives the same bytes as normalising once" {
        $once = Join-Path $work "once.step"; $twice = Join-Path $work "twice.step"
        [void](Set-StepFileHeader -Path $inventorFile -OutPath $once); $second = Set-StepFileHeader -Path $once -OutPath $twice
        Assert ((Get-FileHash -LiteralPath $once).Hash -eq (Get-FileHash -LiteralPath $twice).Hash -and -not $second.changed) "second pass changed the file"
    }
    Case "H5 two exports that differ only in name, time stamp and author normalise to identical bytes" {
        $other = New-Step "other.step" (($inventorHeader.Replace("PLATE__[Primary]__0a1b2c3d.step", "another name.step").Replace("2026-10-21T15:09:10-04:00", "2026-11-10T09:00:00-05:00").Replace("('someone')", "('someone else')")) + $dataSection)
        $a = Join-Path $work "a.step"; $b = Join-Path $work "b.step"
        [void](Set-StepFileHeader -Path $inventorFile -OutPath $a); [void](Set-StepFileHeader -Path $other -OutPath $b)
        Assert ((Get-FileHash -LiteralPath $inventorFile).Hash -ne (Get-FileHash -LiteralPath $other).Hash -and (Get-FileHash -LiteralPath $a).Hash -eq (Get-FileHash -LiteralPath $b).Hash) "normalised files differ"
    }
    Case "H6 a DATA; or ENDSEC; inside a header string or comment is not a section boundary" {
        $tricky = New-Step "tricky.step" ("ISO-10303-21;`nHEADER;`n/* DATA; ENDSEC; */`nFILE_DESCRIPTION(('DATA; in a string'),'2;1');`nFILE_NAME('n.step','t',('it''s; me'),(''),'p','o','');`nFILE_SCHEMA(('AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF { 1 0 10303 442 1 1 4 }'));`nENDSEC;`nDATA;`n#1=X();`nENDSEC;`nEND-ISO-10303-21;`n")
        $info = Get-StepFileInfo -Path $tricky
        $text = $latin1.GetString([IO.File]::ReadAllBytes($tricky))
        Assert ($info.data_offset -eq $text.LastIndexOf("DATA;")) "data offset $($info.data_offset)"
        Assert ((@($info.header.author) -join '|') -eq "it's; me" -and (@($info.header.description) -join '|') -eq "DATA; in a string" -and $info.header.protocol -eq "AP242" -and $info.line_ending -eq "LF") "fields: $(@($info.header.author) -join '|') / $($info.header.protocol) / $($info.line_ending)"
        "author '$(@($info.header.author) -join '|')', protocol $($info.header.protocol)"
    }
    Case "H7 explicit name, time stamp and author are written and quotes are doubled" {
        $out = Join-Path $work "explicit.step"
        $done = Set-StepFileHeader -Path $inventorFile -OutPath $out -Name "it's.step" -TimeStamp "2000-01-01T00:00:00" -Author "vault-cad-tools" -Organization "org" -Authorisation "auth"
        Assert ($done.new_statement -eq "FILE_NAME('it''s.step','2000-01-01T00:00:00',('vault-cad-tools'),('org'),'ST-DEVELOPER v20','Autodesk Inventor 2025','auth');") "statement: $($done.new_statement)"
        $info = Get-StepFileInfo -Path $out
        Assert ($info.header.name -eq "it's.step" -and (@($info.header.author) -join '|') -eq "vault-cad-tools" -and $info.header.authorisation -eq "auth") "fields not read back"
    }
    Case "H8 an existing output file is never overwritten" {
        $out = Join-Path $work "exists.step"; [IO.File]::WriteAllText($out, "keep")
        [void](Throws { Set-StepFileHeader -Path $inventorFile -OutPath $out } 'overwrite')
        Assert ([IO.File]::ReadAllText($out) -eq "keep") "the existing file was changed"
    }
    Case "H9 broken files are refused: no DATA section, no HEADER, unterminated string, no FILE_NAME" {
        $noData = New-Step "nodata.step" "ISO-10303-21;`nHEADER;`nFILE_NAME('a','b',(''),(''),'p','o','');`nENDSEC;`nEND-ISO-10303-21;`n"
        $noHeader = New-Step "noheader.step" "ISO-10303-21;`nDATA;`n#1=X();`nENDSEC;`n"
        $openString = New-Step "openstring.step" "ISO-10303-21;`nHEADER;`nFILE_NAME('a,'b');`nENDSEC;`nDATA;`nENDSEC;`n"
        $noFileName = New-Step "nofilename.step" "ISO-10303-21;`nHEADER;`nFILE_DESCRIPTION((''),'2;1');`nENDSEC;`nDATA;`n#1=X();`nENDSEC;`n"
        [void](Throws { Get-StepFileInfo -Path $noData } 'no DATA section')
        [void](Throws { Get-StepFileInfo -Path $noHeader } 'no HEADER section|not closed')
        [void](Throws { Get-StepFileInfo -Path $openString } 'unterminated|no DATA|not closed')
        [void](Throws { Set-StepFileHeader -Path $noFileName -OutPath (Join-Path $work "x.step") } 'no FILE_NAME')
        Assert (-not (Test-Path -LiteralPath (Join-Path $work "x.step"))) "a file was written for a refused input"
    }
    Case "H10 a non-ASCII header string is refused, nothing written" {
        $accent = New-Step "accent.step" ("ISO-10303-21;`nHEADER;`nFILE_NAME('a','b',(''),(''),'pr" + [char]233 + "','o','');`nENDSEC;`nDATA;`n#1=X();`nENDSEC;`n")
        $out = Join-Path $work "accent-out.step"
        [void](Throws { Set-StepFileHeader -Path $accent -OutPath $out } 'not printable ASCII')
        Assert (-not (Test-Path -LiteralPath $out)) "a file was written"
    }
    Case "H11 the data section is left byte for byte, including a string with a semicolon and an escaped quote" {
        $out = Join-Path $work "databytes.step"; [void](Set-StepFileHeader -Path $inventorFile -OutPath $out)
        $after = $latin1.GetString([IO.File]::ReadAllBytes($out))
        Assert ($after.EndsWith($dataSection) -and $after.Substring($after.Length - $dataSection.Length) -eq $dataSection) "data section text differs"
    }
} finally { Remove-Item -LiteralPath $work -Recurse -Force }
$passed = @($results | Where-Object passed).Count; $failed = @($results | Where-Object { -not $_.passed }).Count
Write-Output "$passed passed, $failed failed"
if ($env:VAULT_CAD_TEST_JSON) { $results | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $env:VAULT_CAD_TEST_JSON -Encoding UTF8 }
if ($failed -gt 0) { exit 1 }
